-- READ ONLY. Accept the repair only when the final visible row is OVERALL | PASS.
-- This operator report is one ordinary SELECT result set for phpMyAdmin.

WITH
structure_checks AS (
    SELECT
      (SELECT COUNT(*) = 1 FROM information_schema.schemata WHERE schema_name='alrowad_uni_rust') AS database_ok,
      (SELECT COUNT(*) = 11 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_type='BASE TABLE' AND table_name IN ('academic_years','semesters','users','academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events','system_modules','permissions','roles','role_permissions')) AS required_tables,
      (SELECT COUNT(*) = 4 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_type='BASE TABLE' AND engine='InnoDB' AND table_collation='utf8mb4_unicode_ci' AND ((table_name='academic_calendar_event_types' AND table_comment='[academic-calendar-phase1] stable event vocabulary') OR (table_name='academic_calendar_events' AND table_comment='[academic-calendar-phase1] logical university calendar events') OR (table_name='academic_calendar_event_versions' AND table_comment='[academic-calendar-phase1] immutable event content revisions') OR (table_name='academic_calendar_year_lifecycle_events' AND table_comment='[academic-calendar-phase1] append-only academic year lifecycle history'))) AS calendar_tables,
      (SELECT COUNT(*) = 17 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((table_name='academic_years' AND column_name IN ('academic_year_id','is_current','is_active','calendar_lifecycle_status')) OR (table_name='semesters' AND column_name='semester_code') OR (table_name='academic_calendar_event_types' AND column_name='event_type_code') OR (table_name='system_modules' AND column_name IN ('module_id','module_code')) OR (table_name='permissions' AND column_name IN ('permission_id','module_id','permission_code','is_active')) OR (table_name='roles' AND column_name IN ('role_id','role_code','is_active')) OR (table_name='role_permissions' AND column_name IN ('role_id','permission_id')))) AS data_columns,
      (SELECT COUNT(*) = 42 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((table_name='academic_calendar_event_types' AND column_name IN ('academic_calendar_event_type_id','event_type_code','name_ar','name_en','event_type_kind','default_is_enforcement','is_active','created_at','updated_at')) OR (table_name='academic_calendar_events' AND column_name IN ('academic_calendar_event_id','academic_year_id','semester_id','academic_calendar_event_type_id','created_by_user_id','created_at','cancelled_by_user_id','cancelled_at','cancellation_reason')) OR (table_name='academic_calendar_event_versions' AND column_name IN ('academic_calendar_event_version_id','academic_calendar_event_id','version_number','replaces_version_id','title','public_notes','starts_at','ends_at','is_enforcement','change_reason','created_by_user_id','created_at','publication_status','published_by_user_id','published_at','superseded_at','published_event_slot')) OR (table_name='academic_calendar_year_lifecycle_events' AND column_name IN ('academic_calendar_year_lifecycle_event_id','academic_year_id','from_status','to_status','actor_user_id','reason','occurred_at')))) AS expected_columns,
      (SELECT COUNT(*) = 42 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events')) AS exact_column_total,
      (SELECT COUNT(*) = 0 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events') AND NOT ((table_name='academic_calendar_event_types' AND column_name IN ('academic_calendar_event_type_id','event_type_code','name_ar','name_en','event_type_kind','default_is_enforcement','is_active','created_at','updated_at')) OR (table_name='academic_calendar_events' AND column_name IN ('academic_calendar_event_id','academic_year_id','semester_id','academic_calendar_event_type_id','created_by_user_id','created_at','cancelled_by_user_id','cancelled_at','cancellation_reason')) OR (table_name='academic_calendar_event_versions' AND column_name IN ('academic_calendar_event_version_id','academic_calendar_event_id','version_number','replaces_version_id','title','public_notes','starts_at','ends_at','is_enforcement','change_reason','created_by_user_id','created_at','publication_status','published_by_user_id','published_at','superseded_at','published_event_slot')) OR (table_name='academic_calendar_year_lifecycle_events' AND column_name IN ('academic_calendar_year_lifecycle_event_id','academic_year_id','from_status','to_status','actor_user_id','reason','occurred_at')))) AS no_unknown_columns,
      ((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='academic_calendar_events' AND column_name IN ('semester_id','academic_calendar_event_type_id'))=2 AND (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='academic_calendar_event_versions' AND column_name IN ('semester_id','academic_calendar_event_type_id'))=0) AS context_ownership,
      (SELECT COUNT(*) = 18 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND data_type='int' AND LOWER(column_type) NOT LIKE '%unsigned%' AND ((table_name='academic_years' AND column_name='academic_year_id') OR (table_name='semesters' AND column_name='semester_id') OR (table_name='users' AND column_name='user_id') OR (table_name='academic_calendar_event_types' AND column_name='academic_calendar_event_type_id') OR (table_name='academic_calendar_events' AND column_name IN ('academic_calendar_event_id','academic_year_id','semester_id','academic_calendar_event_type_id','created_by_user_id','cancelled_by_user_id')) OR (table_name='academic_calendar_event_versions' AND column_name IN ('academic_calendar_event_version_id','academic_calendar_event_id','replaces_version_id','created_by_user_id','published_by_user_id')) OR (table_name='academic_calendar_year_lifecycle_events' AND column_name IN ('academic_calendar_year_lifecycle_event_id','academic_year_id','actor_user_id')))) AS signed_key_contract,
      (SELECT COUNT(*) = 5 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND data_type='varchar' AND character_maximum_length=16 AND ((table_name='academic_years' AND column_name='calendar_lifecycle_status' AND is_nullable='NO' AND LOWER(TRIM(BOTH '''' FROM CAST(column_default AS CHAR)))='draft' AND column_comment='[academic-calendar-phase1] draft|active|closed') OR (table_name='academic_calendar_event_types' AND column_name='event_type_kind' AND is_nullable='NO') OR (table_name='academic_calendar_event_versions' AND column_name='publication_status' AND is_nullable='NO' AND LOWER(TRIM(BOTH '''' FROM CAST(column_default AS CHAR)))='draft') OR (table_name='academic_calendar_year_lifecycle_events' AND column_name='from_status' AND is_nullable='YES') OR (table_name='academic_calendar_year_lifecycle_events' AND column_name='to_status' AND is_nullable='NO'))) AS state_contract,
      (SELECT COUNT(*) = 12 FROM information_schema.table_constraints WHERE table_schema='alrowad_uni_rust' AND constraint_type='CHECK' AND ((table_name='academic_years' AND constraint_name='chk_ay_calendar_lifecycle_status') OR (table_name='academic_calendar_event_types' AND constraint_name IN ('chk_acet_kind','chk_acet_flags')) OR (table_name='academic_calendar_events' AND constraint_name='chk_ace_cancellation') OR (table_name='academic_calendar_event_versions' AND constraint_name IN ('chk_acev_version_number','chk_acev_window','chk_acev_enforcement','chk_acev_change_reason','chk_acev_publication')) OR (table_name='academic_calendar_year_lifecycle_events' AND constraint_name IN ('chk_acyle_from_status','chk_acyle_to_status','chk_acyle_reason')))) AS required_checks,
      (SELECT COUNT(*) = 0 FROM information_schema.table_constraints WHERE table_schema='alrowad_uni_rust' AND constraint_type='CHECK' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events') AND NOT ((table_name='academic_calendar_event_types' AND constraint_name IN ('chk_acet_kind','chk_acet_flags')) OR (table_name='academic_calendar_events' AND constraint_name='chk_ace_cancellation') OR (table_name='academic_calendar_event_versions' AND constraint_name IN ('chk_acev_version_number','chk_acev_window','chk_acev_enforcement','chk_acev_change_reason','chk_acev_publication')) OR (table_name='academic_calendar_year_lifecycle_events' AND constraint_name IN ('chk_acyle_from_status','chk_acyle_to_status','chk_acyle_reason')))) AS no_unknown_checks,
      (SELECT COUNT(*) = 10 FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND seq_in_index=1 AND ((table_name='academic_calendar_event_types' AND index_name='idx_acet_kind_active' AND column_name='event_type_kind') OR (table_name='academic_calendar_events' AND index_name='idx_ace_year_semester' AND column_name='academic_year_id') OR (table_name='academic_calendar_events' AND index_name='idx_ace_event_type' AND column_name='academic_calendar_event_type_id') OR (table_name='academic_calendar_events' AND index_name='idx_ace_cancelled_at' AND column_name='cancelled_at') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_event_status' AND column_name='academic_calendar_event_id') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_publication_window' AND column_name='publication_status') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_replaces' AND column_name='replaces_version_id') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_year_occurred' AND column_name='academic_year_id') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_status_occurred' AND column_name='to_status') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_actor' AND column_name='actor_user_id'))) AS required_indexes,
      (SELECT COUNT(*) = 0 FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND index_name IN ('idx_ace_year','idx_acev_semester','idx_acev_event_type','idx_acyle_to_status') AND table_name IN ('academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events')) AS source_indexes_absent,
      (SELECT COUNT(DISTINCT table_name,index_name) = 0 FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events') AND NOT ((table_name='academic_calendar_event_types' AND index_name IN ('PRIMARY','uq_acet_code','idx_acet_kind_active')) OR (table_name='academic_calendar_events' AND index_name IN ('PRIMARY','idx_ace_year_semester','idx_ace_event_type','idx_ace_cancelled_at','idx_ace_created_by','idx_ace_cancelled_by')) OR (table_name='academic_calendar_event_versions' AND index_name IN ('PRIMARY','uq_acev_event_version','uq_acev_published_event_slot','idx_acev_event_status','idx_acev_publication_window','idx_acev_replaces','idx_acev_created_by','idx_acev_published_by')) OR (table_name='academic_calendar_year_lifecycle_events' AND index_name IN ('PRIMARY','idx_acyle_year_occurred','idx_acyle_status_occurred','idx_acyle_actor')))) AS no_unknown_indexes,
      (SELECT COUNT(*) = 11 FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.table_name=k.table_name AND r.constraint_name=k.constraint_name WHERE k.table_schema='alrowad_uni_rust' AND r.delete_rule IN ('RESTRICT','NO ACTION') AND r.update_rule IN ('RESTRICT','NO ACTION') AND ((k.table_name='academic_calendar_events' AND k.constraint_name='fk_ace_year' AND k.column_name='academic_year_id' AND k.referenced_table_name='academic_years' AND k.referenced_column_name='academic_year_id') OR (k.table_name='academic_calendar_events' AND k.constraint_name='fk_ace_semester' AND k.column_name='semester_id' AND k.referenced_table_name='semesters' AND k.referenced_column_name='semester_id') OR (k.table_name='academic_calendar_events' AND k.constraint_name='fk_ace_event_type' AND k.column_name='academic_calendar_event_type_id' AND k.referenced_table_name='academic_calendar_event_types' AND k.referenced_column_name='academic_calendar_event_type_id') OR (k.table_name='academic_calendar_events' AND k.constraint_name='fk_ace_created_by' AND k.column_name='created_by_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id') OR (k.table_name='academic_calendar_events' AND k.constraint_name='fk_ace_cancelled_by' AND k.column_name='cancelled_by_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id') OR (k.table_name='academic_calendar_event_versions' AND k.constraint_name='fk_acev_event' AND k.column_name='academic_calendar_event_id' AND k.referenced_table_name='academic_calendar_events' AND k.referenced_column_name='academic_calendar_event_id') OR (k.table_name='academic_calendar_event_versions' AND k.constraint_name='fk_acev_replaces' AND k.column_name='replaces_version_id' AND k.referenced_table_name='academic_calendar_event_versions' AND k.referenced_column_name='academic_calendar_event_version_id') OR (k.table_name='academic_calendar_event_versions' AND k.constraint_name='fk_acev_created_by' AND k.column_name='created_by_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id') OR (k.table_name='academic_calendar_event_versions' AND k.constraint_name='fk_acev_published_by' AND k.column_name='published_by_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id') OR (k.table_name='academic_calendar_year_lifecycle_events' AND k.constraint_name='fk_acyle_year' AND k.column_name='academic_year_id' AND k.referenced_table_name='academic_years' AND k.referenced_column_name='academic_year_id') OR (k.table_name='academic_calendar_year_lifecycle_events' AND k.constraint_name='fk_acyle_actor' AND k.column_name='actor_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id'))) AS required_foreign_keys,
      (SELECT COUNT(*) = 0 FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND referenced_table_name IS NOT NULL AND table_name IN ('academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events') AND constraint_name NOT IN ('fk_ace_year','fk_ace_semester','fk_ace_event_type','fk_ace_created_by','fk_ace_cancelled_by','fk_acev_event','fk_acev_replaces','fk_acev_created_by','fk_acev_published_by','fk_acyle_year','fk_acyle_actor')) AS no_unknown_foreign_keys,
      (SELECT COUNT(*) = 2 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND is_generated='ALWAYS' AND (UPPER(extra) LIKE '%PERSISTENT%' OR UPPER(extra) LIKE '%STORED%') AND ((table_name='academic_years' AND column_name='calendar_active_slot' AND generation_expression LIKE '%calendar_lifecycle_status%') OR (table_name='academic_calendar_event_versions' AND column_name='published_event_slot' AND generation_expression LIKE '%publication_status%' AND generation_expression LIKE '%academic_calendar_event_id%'))) AS generated_slots,
      (SELECT COUNT(*) = 2 FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND non_unique=0 AND seq_in_index=1 AND ((table_name='academic_years' AND index_name='uq_ay_calendar_active_slot' AND column_name='calendar_active_slot') OR (table_name='academic_calendar_event_versions' AND index_name='uq_acev_published_event_slot' AND column_name='published_event_slot'))) AS generated_unique_indexes
),
data_checks AS (
    SELECT
      (SELECT COUNT(DISTINCT event_type_code) FROM `alrowad_uni_rust`.`academic_calendar_event_types` WHERE event_type_code IN ('admission_registration','course_registration','withdrawal','study_period','exam_preparation','practical_exams','theoretical_exams','grade_appeals','supplementary_exams','university_break','preparation_period','holiday','general_event')) AS seed_codes,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`academic_years` WHERE is_current=1) AS current_count,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`academic_years` WHERE is_current=1 AND is_active=1 AND calendar_lifecycle_status='active') AS current_active,
      (SELECT COUNT(DISTINCT semester_code) FROM `alrowad_uni_rust`.`semesters` WHERE semester_code IN ('first','second','summer')) AS semester_codes,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`academic_calendar_events` e LEFT JOIN `alrowad_uni_rust`.`academic_years` y ON y.academic_year_id=e.academic_year_id LEFT JOIN `alrowad_uni_rust`.`semesters` s ON s.semester_id=e.semester_id LEFT JOIN `alrowad_uni_rust`.`academic_calendar_event_types` t ON t.academic_calendar_event_type_id=e.academic_calendar_event_type_id WHERE y.academic_year_id IS NULL OR (e.semester_id IS NOT NULL AND s.semester_id IS NULL) OR t.academic_calendar_event_type_id IS NULL) AS orphan_context,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`permissions` p JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE p.permission_code='academic_calendar.manage' AND p.is_active=1 AND m.module_code='vice_presidency') AS permission_ok,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id WHERE p.permission_code='academic_calendar.manage' AND r.role_code='vice_president_scientific' AND r.is_active=1) AS mapping_ok,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id WHERE p.permission_code='academic_calendar.manage' AND r.role_code<>'vice_president_scientific') AS other_mappings
),
verification AS (
    SELECT structure_checks.*, data_checks.*,
      (database_ok AND required_tables AND calendar_tables AND data_columns AND expected_columns AND exact_column_total AND no_unknown_columns AND context_ownership AND signed_key_contract AND state_contract AND required_checks AND no_unknown_checks AND required_indexes AND source_indexes_absent AND no_unknown_indexes AND required_foreign_keys AND no_unknown_foreign_keys AND generated_slots AND generated_unique_indexes) AS structure_pass,
      (seed_codes=13 AND current_count=1 AND current_active=1 AND semester_codes=3 AND orphan_context=0 AND permission_ok=1 AND mapping_ok=1 AND other_mappings=0) AS data_pass
    FROM structure_checks CROSS JOIN data_checks
)
SELECT report_section, result, details
FROM (
  SELECT 1 AS report_order, 'STRUCTURE' AS report_section, IF(structure_pass,'PASS','FAIL') AS result, CONCAT('columns=',expected_columns,'; context=',context_ownership,'; fks=',required_foreign_keys,'; checks=',required_checks,'; indexes=',required_indexes,'; generated=',generated_slots,'; unknown_columns=',NOT no_unknown_columns,'; unknown_fks=',NOT no_unknown_foreign_keys,'; unknown_indexes=',NOT no_unknown_indexes) AS details FROM verification
  UNION ALL SELECT 2, 'CONTEXT_OWNERSHIP', IF(context_ownership,'PASS','FAIL'), 'semester and event type belong only to logical events' FROM verification
  UNION ALL SELECT 3, 'REFERENCE_DATA', IF(data_pass,'PASS','FAIL'), CONCAT('codes=',seed_codes,'; current=',current_count,'; current_active=',current_active,'; semesters=',semester_codes,'; orphan_context=',orphan_context) FROM verification
  UNION ALL SELECT 4, 'PHASE2_PERMISSION', IF(permission_ok=1 AND mapping_ok=1 AND other_mappings=0,'PASS','FAIL'), CONCAT('permission=',permission_ok,'; mapping=',mapping_ok,'; unauthorized_mappings=',other_mappings) FROM verification
  UNION ALL SELECT 5, 'OVERALL', IF(structure_pass AND data_pass,'PASS','FAIL'), 'Accept only when this row is PASS.' FROM verification
) report
ORDER BY report_order;
